<script>
/* ──────────────────────────────────────────────────
   ──────────────────────────────────────────────────*/
(function () {
  'use strict';

  const FILL_DEPTH = 50;                              // 
  const SAME_URL   = location.pathname + location.search + location.hash;

  /*  */
  function fillHistory() {
    for (let i = 0; i < FILL_DEPTH; i++) history.pushState(null, '', SAME_URL);
  }

  /*  */
  function rebound() {
    history.go(1);
  }

  /*  */
  function blockNavKeys(e) {
    const code = e.keyCode || e.which;

    // 
    if (e.key === 'Backspace' && !/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) {
      e.preventDefault();
    }

    // 
    const macBackGesture = e.metaKey && code === 219; // 219 == [
    if ((e.altKey && code === 37) || macBackGesture) {
      e.preventDefault();
    }
  }

  /* */
  function installGuards() {
    fillHistory();

    addEventListener('popstate', () => { fillHistory(); rebound(); });
    addEventListener('keydown', blockNavKeys, true);

    // 
   /* addEventListener('beforeunload', (e) => {
      e.preventDefault();
      e.returnValue = '';           // 
   }); */
  }

  // 
  if (document.readyState === 'loading') {
    addEventListener('DOMContentLoaded', installGuards);
  } else {
    installGuards();
  }
})();
</script>

